<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_permission('manage_products');
if($_SERVER['REQUEST_METHOD']==='POST'&&is_super_admin()){csrf_check();if(($_POST['action']??'')==='toggle'){$id=(int)($_POST['id']??0);db()->prepare('UPDATE products SET active=1-active WHERE id=?')->execute([$id]);audit('PRODUCT_TOGGLE','product',$id);redirect('products.php');}}
$q=trim($_GET['q']??''); $params=[];$cols='p.id,p.sku,p.product_barcode,p.product_name,p.product_image,p.category_id,p.brand,p.fabric,p.color,p.size,p.serial_tracking,p.mrp,p.retail_price,p.wholesale_price,p.active';if(is_super_admin())$cols.=',p.purchase_cost,p.cost_code';$sql='SELECT '.$cols.',c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE 1';if($q!==''){$sql.=' AND (p.sku LIKE ? OR p.product_barcode LIKE ? OR p.product_name LIKE ? OR p.brand LIKE ?)';$like='%'.$q.'%';$params=[$like,$like,$like,$like];}$sql.=' ORDER BY p.id DESC LIMIT 500';$st=db()->prepare($sql);$st->execute($params);$rows=$st->fetchAll();page_header('Products');$saved=flash('product_saved');if($saved)echo '<div class="notice">'.e($saved).'</div>';?>
<div class="actions no-print"><form method="get" style="display:flex;gap:8px;flex:1"><input name="q" value="<?=e($q)?>" placeholder="Search SKU / Barcode / Product / Brand"><button class="btn">Search</button></form><a class="btn" href="product_form.php">+ Add Product</a></div><br>
<table><tr><th>Photo</th><th>SKU</th><th>Product</th><th>Variant</th><th>Tracking</th><th>Barcode</th><?php if(is_super_admin()):?><th>Purchase Cost</th><th>Cost Code</th><?php endif;?><th>Retail</th><th>Wholesale</th><th>MRP</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?php if($r['product_image']):?><img src="<?=e($r['product_image'])?>" alt="" style="width:56px;height:56px;object-fit:cover;border-radius:8px"><?php endif;?></td><td><?=e($r['sku'])?></td><td><?=e($r['product_name'])?><div class="muted"><?=e(($r['brand']??'').' · '.($r['category_name']??'').' · '.($r['fabric']??''))?></div></td><td><?=e(trim(($r['color']??'').' / '.($r['size']??''),' /'))?></td><td><?=$r['serial_tracking']?'<span class="badge">UNIQUE</span>':'<span class="badge">BATCH</span>'?></td><td><?=e($r['product_barcode'])?></td><?php if(is_super_admin()):?><td>₹<?=e(number_format($r['purchase_cost'],2))?></td><td><?=e($r['cost_code'])?></td><?php endif;?><td>₹<?=e(number_format($r['retail_price'],2))?></td><td>₹<?=e(number_format($r['wholesale_price'],2))?></td><td>₹<?=e(number_format($r['mrp'],2))?></td><td><?= $r['active']?'Active':'Inactive' ?></td><td><a href="product_form.php?id=<?=$r['id']?>">Edit</a><?php if(is_super_admin()):?><form method="post" style="display:inline;margin-left:8px"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn secondary" type="submit"><?=$r['active']?'Deactivate':'Activate'?></button></form><?php endif;?></td></tr><?php endforeach;?></table><?php page_footer();
